<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\BelongsTo;
/** Provides employment contract behavior within the WorkIntel application. */ class EmploymentContract extends Model { protected $fillable=['uuid','workspace_id','member_id','previous_contract_id','version','title','contract_type','effective_from','effective_to','status','salary_amount','salary_currency','salary_period','notes','document_id','created_by']; /** Defines attribute casting rules for the model. */ protected function casts():array{return ['effective_from'=>'date','effective_to'=>'date','salary_amount'=>'decimal:2'];} /** Handles the member operation for the current WorkIntel workflow. */ public function member():BelongsTo{return $this->belongsTo(WorkspaceMember::class,'member_id');} /** Handles the document operation for the current WorkIntel workflow. */ public function document():BelongsTo{return $this->belongsTo(EmployeeDocument::class,'document_id');} }
